// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { typedndarray } from '@stdlib/types/ndarray';

/**
* Interface describing `unshift`.
*/
interface Unshift {
	/**
	* Returns a one-dimensional ndarray formed by prepending the provided scalar values to the input ndarray.
	*
	* @param x - input ndarray
	* @param values - scalar values
	* @returns output ndarray
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	*
	* var x = array( [ 1.0, 2.0, 3.0, 4.0 ] );
	*
	* var out = unshift( x, -2.0, -1.0, 0.0 );
	* // returns <ndarray>
	*
	* var arr = ndarray2array( out );
	* // returns [ -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0 ]
	*/
	<T = unknown>( x: typedndarray<T>, ...values: Array<T> ): typedndarray<T>;

	/**
	* Prepends the provided scalar values to the input ndarray and assigns the result to a provided one-dimensional output ndarray.
	*
	* @param x - input ndarray
	* @param values - scalar values
	* @param out - output ndarray
	* @returns output ndarray
	*
	* @example
	* var array = require( '@stdlib/ndarray/array' );
	* var empty = require( '@stdlib/ndarray/empty' );
	* var ndarray2array = require( '@stdlib/ndarray/to-array' );
	*
	* var x = array( [ 1.0, 2.0, 3.0, 4.0 ] );
	* var y = empty( [ 7 ] );
	*
	* var out = unshift.assign( x, -2.0, -1.0, 0.0, y );
	* // returns <ndarray>
	*
	* var bool = ( out === y );
	* // returns true
	*
	* var arr = ndarray2array( y );
	* // returns [ -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0 ]
	*/
	assign<T = unknown, U = unknown, V extends typedndarray<U> = typedndarray<U>>( x: typedndarray<T>, ...values: Array<T>, out: V ): V;
}

/**
* Returns a one-dimensional ndarray formed by prepending the provided scalar values to the input ndarray.
*
* @param x - input ndarray
* @param values - scalar values
* @returns output ndarray
*
* @example
* var array = require( '@stdlib/ndarray/array' );
* var ndarray2array = require( '@stdlib/ndarray/to-array' );
*
* var x = array( [ 1.0, 2.0, 3.0, 4.0 ] );
*
* var out = unshift( x, -2.0, -1.0, 0.0 );
* // returns <ndarray>
*
* var arr = ndarray2array( out );
* // returns [ -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0 ]
*
* @example
* var array = require( '@stdlib/ndarray/array' );
* var empty = require( '@stdlib/ndarray/empty' );
* var ndarray2array = require( '@stdlib/ndarray/to-array' );
*
* var x = array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = empty( [ 7 ] );
*
* var out = unshift.assign( x, -2.0, -1.0, 0.0, y );
* // returns <ndarray>
*
* var bool = ( out === y );
* // returns true
*
* var arr = ndarray2array( y );
* // returns [ -2.0, -1.0, 0.0, 1.0, 2.0, 3.0, 4.0 ]
*/
declare var unshift: Unshift;


// EXPORTS //

export = unshift;
